define(["core/ajax"],function(Ajax){const init=function(bookflowId,trackProgress){document.querySelectorAll(".bookflow-content-tabs").forEach(function(block){const visited=new Set([0]);block.querySelectorAll("[role='tab']").forEach(function(tab){tab.addEventListener("click",function(){const index=Number(tab.dataset.itemIndex);block.querySelectorAll("[role='tab']").forEach(function(item){const active=item===tab;item.classList.toggle("active",active);item.setAttribute("aria-selected",active?"true":"false")});block.querySelectorAll("[role='tabpanel']").forEach(function(panel){panel.classList.toggle("d-none",Number(panel.dataset.panelIndex)!==index)});visited.add(index);if(!trackProgress){return}Ajax.call([{methodname:"mod_bookflow_mark_content_completed",args:{bookflowid:bookflowId,contentid:Number(block.dataset.contentId),metric:visited.size,details:JSON.stringify({visited:Array.from(visited)})}}])[0].catch(function(){})});tab.addEventListener("keydown",function(event){if(!["ArrowLeft","ArrowRight","Home","End"].includes(event.key)){return}event.preventDefault();const tabs=Array.from(block.querySelectorAll("[role='tab']"));const current=tabs.indexOf(tab);let target=current;if(event.key==="ArrowLeft"){target=(current-1+tabs.length)%tabs.length}else if(event.key==="ArrowRight"){target=(current+1)%tabs.length}else if(event.key==="Home"){target=0}else if(event.key==="End"){target=tabs.length-1}tabs[target].focus();tabs[target].click()})})})};return{init:init}});